import{_ as l,a0 as t,w as r,s as o,ao as c,I as p,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const z=JSON.parse('{"title":"如何在 Linux 使用文件壓縮 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 使用文件壓縮 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 使用文件壓縮 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 使用文件壓縮 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171214 How to squeeze the most out of Linux file compression","title":"如何在 Linux 使用文件壓縮","tag":"201801","desc":""},"relativePath":"201801/20171214 How to squeeze the most out of Linux file compression.md","filePath":"[post].md"}'),d={name:"201801/20171214 How to squeeze the most out of Linux file compression.md"};function h(g,s,b,f,u,m){const a=t("Link");return r(),o("div",null,[s[11]||(s[11]=c(`<h1 id="如何在-linux-使用文件壓縮" tabindex="-1">如何在 Linux 使用文件壓縮 <a class="header-anchor" href="#如何在-linux-使用文件壓縮" aria-label="Permalink to “如何在 Linux 使用文件壓縮”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2017/12/snake-bus-100743983-large.jpg" alt=""></p><blockquote><p>Linux 系統為文件壓縮提供了許多選擇，關鍵是選擇一個最適合你的。</p></blockquote><p>如果你對可用於 Linux 系統的文件壓縮命令或選項有任何疑問，你也許應該看一下 <code>apropos compress</code> 這個命令的輸出。如果你有機會這麼做，你會驚異於有如此多的的命令來進行壓縮文件和解壓縮文件；此外還有許多命令來進行壓縮文件的比較、檢驗，並且能夠在壓縮文件中的內容中進行搜索，甚至能夠把壓縮文件從一個格式變成另外一種格式（如，將 <code>.z</code> 格式變為 <code>.gz</code> 格式 ）。</p><p>你可以看到只是適用於 bzip2 壓縮的全部條目就有這麼多。加上 zip、gzip 和 xz 在內，你會有非常多的選擇。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apropos compress | grep ^bz</span></span>
<span class="line"><span>    bzcat (1)            - decompresses files to stdout</span></span>
<span class="line"><span>    bzcmp (1)            - compare bzip2 compressed files</span></span>
<span class="line"><span>    bzdiff (1)           - compare bzip2 compressed files</span></span>
<span class="line"><span>    bzegrep (1)          - search possibly bzip2 compressed files for a regular expression</span></span>
<span class="line"><span>    bzexe (1)            - compress executable files in place</span></span>
<span class="line"><span>    bzfgrep (1)          - search possibly bzip2 compressed files for a regular expression</span></span>
<span class="line"><span>    bzgrep (1)           - search possibly bzip2 compressed files for a regular expression</span></span>
<span class="line"><span>    bzip2 (1)            - a block-sorting file compressor, v1.0.6</span></span>
<span class="line"><span>    bzless (1)           - file perusal filter for crt viewing of bzip2 compressed text</span></span>
<span class="line"><span>    bzmore (1)           - file perusal filter for crt viewing of bzip2 compressed text</span></span></code></pre></div><p>在我的 Ubuntu 系統上 ，<code>apropos compress</code> 命令的返回中列出了 60 條以上的命令。</p><h3 id="壓縮算法" tabindex="-1">壓縮算法 <a class="header-anchor" href="#壓縮算法" aria-label="Permalink to “壓縮算法”">​</a></h3><p>壓縮並沒有普適的方案，某些壓縮工具是有損壓縮，例如一些壓縮用於減少 mp3 文件大小，而能夠使聆聽者有接近原聲的音樂感受。但是在 Linux 命令列上壓縮或歸檔用户文件所使用的算法必須能夠精確地重新恢復為原始數據。換句話説，它們必須是無損的。</p><p>這是如何做到的？讓我們假設在一行上有 300 個相同的字符可以被壓縮成像 “300x” 這樣的字符串，但是這種算法對大多數文件沒有很大的用處，因為文件中不可能包含長的相同字符序列比完全隨機的序列更多。 壓縮算法要複雜得多，從 Unix 早期壓縮首次被引入以來，它就越來越複雜了。</p><h3 id="在-linux-系統上的壓縮命令" tabindex="-1">在 Linux 系統上的壓縮命令 <a class="header-anchor" href="#在-linux-系統上的壓縮命令" aria-label="Permalink to “在 Linux 系統上的壓縮命令”">​</a></h3><p>在 Linux 系統上最常用的文件壓縮命令包括 <code>zip</code>、<code>gzip</code>、<code>bzip2</code>、<code>xz</code>。 所有這些壓縮命令都以類似的方式工作，但是你需要權衡有多少文件要壓縮（節省多少空間）、壓縮花費的時間、壓縮文件在其他你需要使用的系統上的兼容性。</p><p>有時壓縮一個文件並不會花費很多時間和精力。在下面的例子中，被壓縮的文件實際上比原始文件要大。這並不是一個常見情況，但是有可能發生——尤其是在文件內容達到一定程度的隨機性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ time zip bigfile.zip bigfile</span></span>
<span class="line"><span>    adding: bigfile (default 0% )</span></span>
<span class="line"><span>real    0m0.055s</span></span>
<span class="line"><span>user    0m0.000s</span></span>
<span class="line"><span>sys     0m0.016s </span></span>
<span class="line"><span>$ ls -l bigfile*</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   0 12月 20 22:36 bigfile</span></span>
<span class="line"><span>-rw------- 1 root root 164 12月 20 22:41 bigfile.zip</span></span></code></pre></div><p>注意該文件壓縮後的版本（<code>bigfile.zip</code>）比原始文件（<code>bigfile</code>）要大。如果壓縮增加了文件的大小或者減少很少的比例，也許唯一的好處就是便於在線備份。如果你在壓縮文件後看到了下面的信息，你不會從壓縮中得到什麼受益。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> ( defalted 1% )</span></span></code></pre></div><p>文件內容在文件壓縮的過程中有很重要的作用。在上面文件大小增加的例子中是因為文件內容過於隨機。壓縮一個文件內容只包含 <code>0</code> 的文件，你會有一個相當震驚的壓縮比。在如此極端的情況下，三個常用的壓縮工具都有非常棒的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r-- 1 shs shs 10485760 Dec 8 12:31 zeroes.txt</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 49 Dec 8 17:28 zeroes.txt.bz2</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10219 Dec 8 17:28 zeroes.txt.gz</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 1660 Dec 8 12:31 zeroes.txt.xz</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10360 Dec 8 12:24 zeroes.zip</span></span></code></pre></div><p>令人印象深刻的是，你不太可能看到超過 1000 萬字節而壓縮到少於 50 字節的文件, 因為基本上不可能有這樣的文件。</p><p>在更真實的情況下 ，大小差異總體上是不同的，但是差別並不顯著，比如對於確實不太大的 jpg 圖片文件來説。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-r--r-- 1 shs shs 13522 Dec 11 18:58 image.jpg</span></span>
<span class="line"><span>-rw-r--r-- 1 shs shs 13875 Dec 11 18:58 image.jpg.bz2</span></span>
<span class="line"><span>-rw-r--r-- 1 shs shs 13441 Dec 11 18:58 image.jpg.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 shs shs 13508 Dec 11 18:58 image.jpg.xz</span></span>
<span class="line"><span>-rw-r--r-- 1 shs shs 13581 Dec 11 18:58 image.jpg.zip</span></span></code></pre></div><p>在對大的文本文件同樣進行壓縮時 ，你會看到顯著的不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l textfile*</span></span>
<span class="line"><span>    -rw-rw-r-- 1 shs shs 8740836 Dec 11 18:41 textfile</span></span>
<span class="line"><span>    -rw-rw-r-- 1 shs shs 1519807 Dec 11 18:41 textfile.bz2</span></span>
<span class="line"><span>    -rw-rw-r-- 1 shs shs 1977669 Dec 11 18:41 textfile.gz</span></span>
<span class="line"><span>    -rw-rw-r-- 1 shs shs 1024700 Dec 11 18:41 textfile.xz</span></span>
<span class="line"><span>    -rw-rw-r-- 1 shs shs 1977808 Dec 11 18:41 textfile.zip</span></span></code></pre></div><p>在這種情況下 ，<code>xz</code> 相較於其他壓縮命令有效的減小了文件大小，對於第二的 bzip2 命令也是如此。</p><h3 id="查看壓縮文件" tabindex="-1">查看壓縮文件 <a class="header-anchor" href="#查看壓縮文件" aria-label="Permalink to “查看壓縮文件”">​</a></h3><p>這些以 <code>more</code> 結尾的命令（<code>bzmore</code> 等等）能夠讓你查看壓縮文件的內容而不需要解壓文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bzmore (1) - file perusal filter for crt viewing of bzip2 compressed text</span></span>
<span class="line"><span>lzmore (1) - view xz or lzma compressed (text) files</span></span>
<span class="line"><span>xzmore (1) - view xz or lzma compressed (text) files</span></span>
<span class="line"><span>zmore (1) - file perusal filter for crt viewing of compressed text</span></span></code></pre></div><p>為了解壓縮文件內容顯示給你，這些命令做了大量的計算。但在另一方面，它們不會把解壓縮後的文件留在你係統上，它們只是即時解壓需要的部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xzmore textfile.xz | head -1</span></span>
<span class="line"><span>    Here is the agenda for tomorrow&#39;s staff meeting:</span></span></code></pre></div><h3 id="比較壓縮文件" tabindex="-1">比較壓縮文件 <a class="header-anchor" href="#比較壓縮文件" aria-label="Permalink to “比較壓縮文件”">​</a></h3><p>有幾個壓縮工具箱包含一個差異命令（例如 ：<code>xzdiff</code>），那些工具會把這些工作交給 <code>cmp</code> 和 <code>diff</code> 來進行比較，而不是做特定算法的比較。例如，<code>xzdiff</code> 命令比較 bz2 類型的文件和比較 xz 類型的文件一樣簡單 。</p><h3 id="如何選擇最好的-linux-壓縮工具" tabindex="-1">如何選擇最好的 Linux 壓縮工具 <a class="header-anchor" href="#如何選擇最好的-linux-壓縮工具" aria-label="Permalink to “如何選擇最好的 Linux 壓縮工具”">​</a></h3><p>如何選擇壓縮工具取決於你工作。在一些情況下，選擇取決於你所壓縮的數據內容。在更多的情況下，取決你組織內的慣例，除非你對磁盤空間有着很高的敏感度。下面是一般性建議：</p><p><strong>zip</strong> 對於需要分享給或者在 Windows 系統下使用的文件最適合。</p><p><strong>gzip</strong> 或許對你要在 Unix/Linux 系統下使用的文件是最好的。雖然 bzip2 已經接近普及，但 gzip 看起來仍將長期存在。</p><p><strong>bzip2</strong> 使用了和 gzip 不同的算法，並且會產生比 gzip 更小的文件，但是它們需要花費更長的時間進行壓縮。</p><p><strong>xz</strong> 通常可以提供最好的壓縮率，但是也會花費相當長的時間。它比其他工具更新一些，可能在你工作的系統上還不存在。</p><h3 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to “注意”">​</a></h3><p>在壓縮文件時，你有很多選擇，而在極少的情況下，並不能有效節省磁盤存儲空間。</p><hr>`,40)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3240938/linux/how-to-squeeze-the-most-out-of-linux-file-compression.html"},{default:n(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3240938/linux/how-to-squeeze-the-most-out-of-linux-file-compression.html",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=e("作者：",-1)),i(a,{href:"https://www.networkworld.com"},{default:n(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),i(a,{href:"https://github.com/singledo"},{default:n(()=>[...s[3]||(s[3]=[e("singledo",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[e(" LCTT ",-1)])]),_:1}),s[10]||(s[10]=e("原創編譯，Linux中國 榮譽推出",-1))])])}const w=l(d,[["render",h]]);export{z as __pageData,w as default};
